use std::fs
use std::collections::HashMap

fn count_of(counts: HashMap<string, int>, w: string) -> int {
    match counts.get(w) {
        Some(v) => v,
        None => 0,
    }
}

fn bump(counts: HashMap<string, int>, w: string) {
    let n = count_of(counts, w)
    counts.insert(w, n + 1)
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut k = 0
    let mut first = true
    let mut counts = HashMap::new()
    for line in text.lines() {
        if first {
            first = false
            for ch in line.chars() {
                let d = "0123456789".find(ch.to_string())
                match d {
                    Some(x) => { k = k * 10 + x as i64 }
                    None => {}
                }
            }
            continue
        }
        let mut cur = ""
        for c in line.chars() {
            if c.is_ascii_alphanumeric() {
                cur = cur + c.to_lowercase().to_string()
            } else {
                if cur.len() > 0 {
                    bump(counts, cur)
                    cur = ""
                }
            }
        }
        if cur.len() > 0 {
            bump(counts, cur)
        }
    }
    let mut items: Vec<string> = []
    for key in counts.keys() {
        let c: int = 1000000000 - count_of(counts, key)
        items.push("${c:010} ${key}")
    }
    items.sort()
    let mut i = 0
    for it in items {
        if i >= k {
            break
        }
        let parts: Vec<string> = it.split(" ").collect()
        let c: int = 1000000000 - parts[0].parse::<int>().unwrap_or(0)
        println("${parts[1]} ${c}")
        i += 1
    }
}

